insert into public.proyectos (id, carrera, orden, publicado, datos) values
  ('casa-moderna', 'arquitectura', 10, true,
   $vitrina${"tipo":"maqueta","titulo":"Casa Moderna","ejemplo":true,"ubicacion":"","estudiante":"Madeleine Morales","materia":"[EJEMPLO] Materia por confirmar","periodo":"Semestre 2 - 2026","descripcion":"Vivienda unifamiliar de dos plantas y terraza de cubierta, con una huella aproximada de 14,8 × 6,4 m y 129,14 m² de área bruta. La planta baja agrupa la zona social: hall de acceso en el volumen revestido de madera, sala de doble altura frente al muro cortina, comedor bajo el mezzanine y cocina independiente; el garaje integra lavandería, calentador y baño de visitas. En la planta alta, la escalera de huella abierta llega al mezzanine (sala de TV), que distribuye al dormitorio master; el ala izquierda reúne el estudio, el baño general y el dormitorio 2, y desde la terraza parte la escalera a la cubierta.","portada":"img/casa-moderna-render.webp","imagenes":[],"creditoModelo":{"titulo":"Modern Home","autor":"Ciolan-T. Sebastian","plataforma":"Sketchfab","url":"https://skfb.ly/6Yr8Q","licencia":"CC BY 4.0","licenciaUrl":"https://creativecommons.org/licenses/by/4.0/","adaptacion":"Diana Espinoza","cambios":"Interiores, mobiliario y planos elaborados sobre el modelo original; para la vitrina se optimizó para celular."},"ar":{"modelo":"modelos/casa-moderna.glb","poster":"img/casa-moderna-render.webp","modeloIOS":"","escala":"1:25","camara":"25deg 62deg 80%","cortes":[{"nombre":"Sin techo","altura":0.234},{"nombre":"Planta baja","altura":0.116}],"alt":"Maqueta 3D de una casa moderna de dos plantas con fachada blanca, volumen revestido de madera, muro cortina de doble altura, garaje y terraza en la cubierta","puntos":[{"id":"sala","titulo":"Sala de doble altura","texto":"La sala tiene doble altura frente al muro cortina de 6 paños (3,42 × 5,08 m), que ilumina también el mezzanine de la planta alta.","posicion":"0.0642 0.056 0.0648","normal":"0 0 1"},{"id":"dormitorio","titulo":"Dormitorio master","texto":"Dormitorio master de 10,54 m² con piso de madera, en la planta alta. Se llega por el mezzanine (sala de TV), al que conduce la escalera de huella abierta.","posicion":"0.2082 0.152 0.0088","normal":"0 1 0"},{"id":"terraza","titulo":"Terraza de cubierta","texto":"Terraza de 22,04 m² sobre la cubierta, con deck y jardineras. Se sube por la escalera que parte de la terraza de la planta alta.","posicion":"-0.1558 0.264 0.0008","normal":"0 1 0"}]},"asistente":{"sugeridas":["¿Cuántos metros tiene la casa?","¿Qué hay en la planta alta?","¿Dónde está el garaje?"],"pasajes":[{"punto":"sala","texto":"La sala tiene doble altura y está frente a un muro cortina de vidrio de 6 paños, de 3,42 × 5,08 m.","claves":["sala","doble altura","ventanal","muro cortina","vidrio","ventana","luz"]},{"punto":null,"texto":"En la planta baja están el hall de acceso, la sala de doble altura, el comedor bajo el mezzanine y la cocina independiente con ventanas al este.","claves":["planta baja","cocina","comedor","hall","entrada","primer piso"]},{"punto":"dormitorio","texto":"La planta alta tiene el dormitorio master (10,54 m²), el dormitorio 2 (6,26 m²), el estudio, el baño general y la sala de TV en el mezzanine.","claves":["planta alta","dormitorio","dormitorios","habitación","habitaciones","cuartos","master","segundo piso","estudio"]},{"punto":null,"texto":"El garaje mide 17,86 m², tiene piso de concreto pulido y un portón seccional de aluminio; integra la lavandería, el calentador y el baño de visitas.","claves":["garaje","garage","cochera","auto","carro","lavandería","portón"]},{"punto":null,"texto":"La vivienda tiene 129,14 m² de área bruta construida: 72,75 m² en planta baja y 56,39 m² en planta alta, con una huella aproximada de 14,8 × 6,4 m.","claves":["metros","m2","área","tamaño","grande","mide","superficie","cuánto"]},{"punto":"terraza","texto":"La terraza de cubierta mide 22,04 m² y tiene deck y jardineras; además, la planta alta tiene una terraza de 7,10 m² con deck de madera.","claves":["terraza","cubierta","azotea","techo","deck","jardinera"]},{"punto":null,"texto":"Los muros son blancos; los pisos sociales y de dormitorios son de madera de acacia, los baños de porcelanato gris y las barandas de vidrio templado con pasamanos de acero inoxidable. El hall está en un volumen revestido de madera.","claves":["material","materiales","madera","piso","acabado","acabados","baranda","color","blanco","fachada"]},{"punto":null,"texto":"Una escalera de huella abierta sube al mezzanine (sala de TV) y, desde la terraza de la planta alta, otra escalera llega a la cubierta.","claves":["escalera","escaleras","gradas","subir","mezzanine"]},{"punto":null,"texto":"Es un proyecto de ejemplo de la estudiante Madeleine Morales para la vitrina de Arquitectura.","claves":["estudiante","autor","autora","quién","hizo","diseñó","materia"]}]},"galeria":{"titulo":"Planos","estilo":"planos","imagenes":[{"src":"img/planos/A-01_Planta_Baja.webp","mini":"img/planos/A-01_Planta_Baja-mini.webp","titulo":"Planta baja","alt":"Plano de la planta baja con garaje y lavandería, baño de visitas, hall, sala de doble altura, comedor y cocina"},{"src":"img/planos/A-02_Planta_Alta.webp","mini":"img/planos/A-02_Planta_Alta-mini.webp","titulo":"Planta alta","alt":"Plano de la planta alta con dormitorio master, dormitorio 2, estudio, baño general, sala de TV en el mezzanine y terraza"},{"src":"img/planos/A-03_Planta_Cubierta.webp","mini":"img/planos/A-03_Planta_Cubierta-mini.webp","titulo":"Planta de cubierta","alt":"Plano de la cubierta con la terraza, las jardineras y la escalera de acceso"},{"src":"img/planos/A-04_Fachadas_Frontal_Posterior.webp","mini":"img/planos/A-04_Fachadas_Frontal_Posterior-mini.webp","titulo":"Fachadas frontal y posterior","alt":"Fachadas frontal y posterior de la vivienda"},{"src":"img/planos/A-05_Fachadas_Laterales.webp","mini":"img/planos/A-05_Fachadas_Laterales-mini.webp","titulo":"Fachadas laterales","alt":"Fachadas laterales de la vivienda"},{"src":"img/planos/A-06_Cortes.webp","mini":"img/planos/A-06_Cortes-mini.webp","titulo":"Cortes","alt":"Cortes de la vivienda que muestran la doble altura de la sala y los niveles"},{"src":"img/planos/A-07_Plantas_Presentacion.webp","mini":"img/planos/A-07_Plantas_Presentacion-mini.webp","titulo":"Plantas de presentación","alt":"Vistas cenitales a color de la planta baja y la planta alta con los ambientes amoblados"},{"src":"img/planos/A-08_Cuadros_y_Memoria.webp","mini":"img/planos/A-08_Cuadros_y_Memoria-mini.webp","titulo":"Cuadros y memoria","alt":"Cuadro de áreas, cuadro de puertas y ventanas, cuadro de acabados y memoria descriptiva"},{"src":"img/planos/A-09_Perspectivas.webp","mini":"img/planos/A-09_Perspectivas-mini.webp","titulo":"Perspectivas","alt":"Perspectivas exteriores de la vivienda"}]}}$vitrina$::jsonb),
  ('cuentos-y-espias', 'multimedia', 20, true,
   $vitrina${"tipo":"video","titulo":"Bienvenidos a Cuentos y Espías","ubicacion":"Campus Samborondón","estudiante":"Diana Espinoza","materia":"Efectos Audiovisuales","periodo":"APE1 · 2026-2","descripcion":"Video de motion graphics con tipografía animada para la canción «Bienvenidos a Cuentos y Espías». La letra la escribió la estudiante Diana Espinoza y la música se generó con Suno AI para un concurso de webtoon; después la estudiante la convirtió en su proyecto universitario. Un televisor retro, rayas de colores, siluetas de ciudad y personajes animados acompañan cada verso. Duración: 1 min 07 s.","portada":"img/cuentos-y-espias-45s.jpg","imagenes":[],"video":"videos/cuentos-y-espias.mp4","poster":"img/cuentos-y-espias-45s.jpg","ar":{"modelo":"modelos/pantalla-cine.glb","pantallaHero":"img/cuentos-y-espias-pantalla.webp","modeloIOS":"","escala":"60 cm de ancho","modos":["televisor","sin-televisor","360"],"modoInicial":"televisor","alt":"Televisor retro azul con una pantalla de cine 16:9 que reproduce el video Cuentos y Espías","puntos":[]},"creditos":{"letra":"Diana Espinoza","musica":"Generada con Suno AI a partir de la letra de la estudiante","origen":"Concurso de webtoon; luego proyecto universitario (Efectos Audiovisuales, APE1)","animacion":"Diana Espinoza"},"subtitulos":"videos/cuentos-y-espias.es.vtt","letra":[{"seccion":"Verso 1","lineas":["Entra al cuento, se va a romper","Una espía lo viene a tejer","Giran los hilos sin control","¿Quién está tras del telón?"]},{"seccion":"Verso 2","lineas":["Cielos de papel, tinta sin ley","Un pato jefe que mantiene el control","Un gran equipo que sabe mentir","Corre, o el final te va a seguir..."]},{"seccion":"Pre-Coro","lineas":["No todo villano es cruel (¡cruel!)","No todo héroe es fiel (¡fiel!)","Ella escribe lo que se fue","Corrigiendo lo que no se ve..."]},{"seccion":"Coro","lineas":["¡Cuentos y Espías! (¡pa-pa-pa!)","Bailan secretos bajo un antifaz","Rompe el guion, sin mirar atrás","Un error y el cuento se fracturará","¡Cuentos y Espías! (¡ja-ja-ja!)","Cazan mentiras en espiral","Entre códigos y tu antifaz","La verdad es el gran disfraz..."]}]}$vitrina$::jsonb),
  ('oficina', 'arquitectura', 30, true,
   $vitrina${"tipo":"maqueta","titulo":"Oficina Loft 18","ejemplo":true,"ubicacion":"","estudiante":"Alberto Urgilés","materia":"[EJEMPLO] Materia por confirmar","periodo":"Semestre 2 - 2026","descripcion":"Oficina tipo loft de dos niveles, con una huella aproximada de 15,3 × 10,0 m, planta en forma de «L» escalonada y 199,67 m² útiles. La planta baja es una zona abierta a doble altura que integra la recepción, una sala de reuniones para 6 personas, un lounge con sofá en «L» y una zona de café junto a la fachada acristalada este; hacia el sur hay tres oficinas privadas y, en el núcleo oeste, los servicios higiénicos. Una escalera recta adosada al muro norte sube al mezzanine en «L» (+2,59 m), con cafetería, bodega, sala de descanso, coworking y una segunda sala de reuniones, protegido por una baranda de vidrio templado. La cubierta es una losa plana con parapeto.","portada":"img/oficina-render.webp","imagenes":[],"galeria":{"titulo":"Planos","estilo":"planos","imagenes":[{"src":"img/oficina/O-01_Planta_Baja.webp","mini":"img/oficina/O-01_Planta_Baja-mini.webp","titulo":"Planta baja","alt":"Plano de la planta baja con recepción, sala de reuniones, lounge a doble altura, zona de café, servicios higiénicos y tres oficinas"},{"src":"img/oficina/O-02_Planta_Alta.webp","mini":"img/oficina/O-02_Planta_Alta-mini.webp","titulo":"Planta alta","alt":"Plano del mezzanine en L con cafetería, bodega, sala de descanso, coworking y sala de reuniones 2"},{"src":"img/oficina/O-03_Planta_Cubierta.webp","mini":"img/oficina/O-03_Planta_Cubierta-mini.webp","titulo":"Planta de cubierta","alt":"Plano de la cubierta plana con parapeto perimetral"},{"src":"img/oficina/O-04_Fachadas_Sur_Norte.webp","mini":"img/oficina/O-04_Fachadas_Sur_Norte-mini.webp","titulo":"Fachadas sur y norte","alt":"Fachadas sur y norte de la oficina"},{"src":"img/oficina/O-05_Fachadas_Este_Oeste.webp","mini":"img/oficina/O-05_Fachadas_Este_Oeste-mini.webp","titulo":"Fachadas este y oeste","alt":"Fachadas este y oeste, con la fachada acristalada de la zona de café"},{"src":"img/oficina/O-06_Cortes.webp","mini":"img/oficina/O-06_Cortes-mini.webp","titulo":"Cortes","alt":"Cortes de la oficina que muestran la doble altura y el mezzanine"},{"src":"img/oficina/O-07_Plantas_Presentacion.webp","mini":"img/oficina/O-07_Plantas_Presentacion-mini.webp","titulo":"Plantas de presentación","alt":"Plantas a color de los dos niveles con el mobiliario"},{"src":"img/oficina/O-08_Cuadro_Areas_Memoria.webp","mini":"img/oficina/O-08_Cuadro_Areas_Memoria-mini.webp","titulo":"Cuadro de áreas y memoria","alt":"Cuadro de áreas por ambiente y memoria descriptiva"}]},"creditoModelo":{"titulo":"free Loft 18 mini office v.optimization","autor":"dasy444","plataforma":"Sketchfab","url":"https://sketchfab.com/3d-models/free-loft-18-mini-office-voptimization-e434caaeaa4a4347a3c45eac6c138c30","licencia":"Sketchfab Standard (gratuita)","licenciaUrl":"https://sketchfab.com/licenses","adaptacion":"Xavier Ponce","cambios":"Planos elaborados a partir del modelo original; para la vitrina se optimizó para celular."},"ar":{"modelo":"modelos/oficina.glb","modeloHero":"modelos/oficina-hero.glb","poster":"img/oficina-render.webp","modeloIOS":"","escala":"1:30","camara":"28deg 64deg 95%","camaraHero":"28deg 64deg 95%","cortes":[{"nombre":"Sin techo","altura":0.1841},{"nombre":"Planta baja","altura":0.1041}],"alt":"Maqueta 3D de una oficina tipo loft de dos niveles, con fachada blanca, grandes ventanales y cubierta plana negra","puntos":[{"id":"lounge","titulo":"Lounge a doble altura","texto":"El lounge, de 41,90 m², tiene doble altura y un sofá en «L»; desde aquí se ve el mezzanine de la planta alta.","posicion":"0.0472 0.0741 0","normal":"0 1 0"},{"id":"mezzanine","titulo":"Mezzanine en «L»","texto":"En la planta alta (+2,59 m), el mezzanine reúne cafetería, coworking, sala de descanso y una segunda sala de reuniones, con baranda de vidrio templado hacia los vacíos.","posicion":"-0.1395 0.1374 -0.0667","normal":"0 1 0"},{"id":"cafe","titulo":"Fachada acristalada","texto":"La zona de café (19,10 m²) está junto a la fachada acristalada este, que deja entrar la luz a la planta abierta.","posicion":"0.2539 0.0774 -0.08","normal":"1 0 0"}]},"asistente":{"sugeridas":["¿Cuántos metros tiene la oficina?","¿Qué hay en la planta alta?","¿Cuántas oficinas privadas tiene?"],"pasajes":[{"punto":null,"texto":"La oficina tiene 199,67 m² útiles: 128,97 m² en planta baja y 70,71 m² en planta alta, con una huella aproximada de 15,3 × 10,0 m.","claves":["metros","m2","área","tamaño","grande","mide","superficie","cuánto"]},{"punto":null,"texto":"En la planta baja están la recepción, la sala de reuniones para 6 personas, el lounge a doble altura, la zona de café, los servicios higiénicos y tres oficinas privadas.","claves":["planta baja","primer piso","recepción","entrada","reuniones"]},{"punto":null,"texto":"Hay tres oficinas privadas hacia el sur, separadas por tabiques: la oficina 1 (17,28 m², a doble altura), la oficina 2 (11,68 m²) y la oficina 3 (12,70 m²).","claves":["oficinas","oficina","privadas","despacho","despachos","cuántas"]},{"punto":"mezzanine","texto":"La planta alta es un mezzanine en «L» con cafetería (16,10 m²), bodega, sala de descanso, coworking (15,36 m²) y una segunda sala de reuniones.","claves":["planta alta","segundo piso","mezzanine","coworking","descanso","arriba"]},{"punto":"lounge","texto":"El lounge mide 41,90 m², tiene doble altura y un sofá en «L».","claves":["lounge","sala","doble altura","sofá","estar"]},{"punto":null,"texto":"A la planta alta se sube por una escalera recta de un tramo, adosada al muro norte.","claves":["escalera","escaleras","gradas","subir"]},{"punto":"cafe","texto":"La zona de café está junto a la fachada acristalada este; la baranda del mezzanine también es de vidrio templado.","claves":["café","vidrio","ventana","ventanal","fachada","luz","cafetería"]},{"punto":null,"texto":"La cubierta es una losa plana con parapeto perimetral, a +4,83 m.","claves":["cubierta","techo","azotea","losa","altura"]},{"punto":null,"texto":"Es un proyecto de ejemplo del estudiante Alberto Urgilés para la vitrina de Arquitectura.","claves":["estudiante","autor","quién","hizo","diseñó","materia"]}]}}$vitrina$::jsonb),
  ('deliveryrush', 'multimedia', 40, true,
   $vitrina${"tipo":"escenario","titulo":"Next Order: Delivery Rush","ubicacion":"","estudiante":"Arllys Ramos y Xavier Ponce","materia":"Virtual Games","periodo":"Semestre 2 - 2026","descripcion":"Videojuego de realidad virtual de simulación y arcade para jugadores casuales desde los 12 años. Trabajas el turno nocturno en una cafetería estilo dark kitchen: lees el pedido en el monitor, descifras los códigos escondidos en notas adhesivas para abrir la despensa y el refrigerador con un teclado virtual, esquivas al robot de limpieza Pac-Cleaner, que se averió y patrulla el pasillo, y llevas cada producto a su sensor de validación antes de pulsar el botón de despacho. Aquí se ve el mapa del nivel 1 como un diorama para la mesa.","portada":"img/deliveryrush-render.webp","imagenes":[],"galeria":{"titulo":"Documento de diseño (GDD)","estilo":"documento","imagenes":[{"src":"img/deliveryrush/gdd-01.webp","mini":"img/deliveryrush/gdd-01-mini.webp","titulo":"1. Portada","alt":"Portada del documento de diseño: Next Order, Delivery Rush, de Arllys Ramos y Xavier Ponce"},{"src":"img/deliveryrush/gdd-02.webp","mini":"img/deliveryrush/gdd-02-mini.webp","titulo":"2. Género, público y objetivo","alt":"Género simulación y arcade, público objetivo, temática, contexto narrativo y objetivo del jugador"},{"src":"img/deliveryrush/gdd-03.webp","mini":"img/deliveryrush/gdd-03-mini.webp","titulo":"3. Reglas y ciclo de juego","alt":"Reglas del juego y ciclo de juego: lectura, exploración, recolección, esquive, validación y despacho"},{"src":"img/deliveryrush/gdd-04.webp","mini":"img/deliveryrush/gdd-04-mini.webp","titulo":"4. Retos, errores y victoria","alt":"Secuencia de 3 retos, consecuencias de errores y contacto, y requisitos de victoria"},{"src":"img/deliveryrush/gdd-05.webp","mini":"img/deliveryrush/gdd-05-mini.webp","titulo":"5. Mecánicas 1 y 2","alt":"Mecánica 1, desplazamiento en VR con la palanca, y mecánica 2, agarre y manipulación con el botón Grip"},{"src":"img/deliveryrush/gdd-06.webp","mini":"img/deliveryrush/gdd-06-mini.webp","titulo":"6. Mecánicas 3 y 4","alt":"Mecánica 3, interacción con la interfaz, y mecánica 4, teclado virtual de 4 dígitos"},{"src":"img/deliveryrush/gdd-07.webp","mini":"img/deliveryrush/gdd-07-mini.webp","titulo":"7. Mecánica 5","alt":"Mecánica 5, validación de productos en los sensores A y B"},{"src":"img/deliveryrush/gdd-08.webp","mini":"img/deliveryrush/gdd-08-mini.webp","titulo":"8. Plano del nivel 1","alt":"Plano del nivel 1 con la dark kitchen, el pasillo del Pac-Cleaner, el teclado virtual y la estación de entrega"},{"src":"img/deliveryrush/gdd-09.webp","mini":"img/deliveryrush/gdd-09-mini.webp","titulo":"9. Propuesta de ambientación","alt":"Dos imágenes de ambientación de la cocina con el monitor de pedidos, el robot y la estación de entrega"},{"src":"img/deliveryrush/gdd-10.webp","mini":"img/deliveryrush/gdd-10-mini.webp","titulo":"10. Pantallas y widgets","alt":"Diseño del monitor de pedidos y del teclado virtual de seguridad"},{"src":"img/deliveryrush/gdd-11.webp","mini":"img/deliveryrush/gdd-11-mini.webp","titulo":"11. Pantalla de victoria","alt":"Pantalla de nivel completado con el botón para reiniciar el nivel"},{"src":"img/deliveryrush/gdd-12.webp","mini":"img/deliveryrush/gdd-12-mini.webp","titulo":"12. Recursos externos y aporte propio","alt":"Fuentes de recursos externos y aporte propio del equipo: modelado, interfaz y programación en Blueprints"}]},"creditos":[{"etiqueta":"Desarrollo","texto":"Modelado en Blender · Desarrollado en Unreal Engine 5"},{"etiqueta":"Modelos y props","texto":"Todos los modelos y props del escenario son originales del equipo."}],"ar":{"modelo":"modelos/deliveryrush.glb","modeloHero":"modelos/deliveryrush-hero.glb","poster":"img/deliveryrush-render.webp","modeloIOS":"","escala":"1:12","camara":"25deg 50deg 75%","camaraHero":"25deg 50deg 78%","cortes":[{"nombre":"Sin vigas","altura":0.2126},{"nombre":"Muros bajos","altura":0.1292}],"alt":"Diorama 3D del nivel 1 de un videojuego: una cafetería sin techo con cocina, pasillo, vitrinas de postres y estación de entrega","puntos":[{"id":"pedidos","titulo":"Monitor de pedidos","texto":"Aquí empieza el nivel: el monitor de la cocina muestra la orden activa (por ejemplo, 1 postre y 1 bebida). Cerca está la nota adhesiva con el primer código.","posicion":"-0.3626 0.1126 0.1906","normal":"1 0 0"},{"id":"pac-cleaner","titulo":"Pac-Cleaner","texto":"El robot de limpieza se averió y patrulla el pasillo principal. Si te choca, te empuja y te desorienta: pierdes tiempo, pero la partida no se reinicia.","posicion":"-0.0458 0.075 0.224","normal":"0 1 0"},{"id":"entrega","titulo":"Estación de entrega","texto":"La meta: cada producto va a su sensor (A para la comida, B para la bebida). Con los dos en verde, pulsas el botón de despacho y completas el nivel.","posicion":"0.4416 0.0958 0.253","normal":"0 1 0"}]},"asistente":{"sugeridas":["¿De qué trata el juego?","¿Cómo se juega?","¿Cómo se gana el nivel?"],"pasajes":[{"punto":null,"texto":"Next Order: Delivery Rush es un juego de realidad virtual de simulación y arcade, para jugadores casuales desde los 12 años. Trabajas el turno nocturno en una cafetería estilo dark kitchen y debes despachar los pedidos.","claves":["juego","trata","historia","género","tema","público","edad","qué es"]},{"punto":"pedidos","texto":"El nivel empieza en el monitor de pedidos de la cocina, que muestra la orden activa; cerca está la nota con el primer código.","claves":["inicio","empieza","monitor","pantalla","pedido","pedidos","orden","comenzar"]},{"punto":null,"texto":"La despensa y el refrigerador están bloqueados. Los códigos de 4 dígitos están en notas adhesivas del escenario y se escriben en el teclado virtual; si te equivocas, puedes intentarlo otra vez sin penalización.","claves":["código","códigos","teclado","clave","contraseña","desbloquear","despensa","refrigerador","nota"]},{"punto":"pac-cleaner","texto":"El Pac-Cleaner es un robot de limpieza averiado que patrulla el pasillo principal. Si te choca, te empuja y te desorienta, pero no reinicia la partida.","claves":["robot","pac","cleaner","enemigo","limpieza","choca","pasillo","obstáculo"]},{"punto":"entrega","texto":"Para ganar, validas dos pedidos: llevas cada producto a su sensor (A para la comida, B para la bebida) y pulsas el botón de despacho. Si el objeto no es el correcto, el sensor se enciende en rojo.","claves":["ganar","gana","victoria","meta","sensor","despacho","entregar","validar","botón","completar"]},{"punto":null,"texto":"Te mueves con la palanca analógica, agarras los productos con el botón Grip y presionas los botones de las pantallas con el gatillo o tocándolos con la mano virtual.","claves":["controles","control","mover","moverse","agarrar","palanca","gatillo","grip","mando","juega","jugar"]},{"punto":null,"texto":"El nivel 1 tiene cuatro zonas: la dark kitchen con el monitor de pedidos, el pasillo principal del Pac-Cleaner, la zona del teclado virtual con las vitrinas de postres y refrescos, y la estación de entrega.","claves":["zonas","mapa","nivel","plano","cocina","partes","escenario"]},{"punto":null,"texto":"El escenario se modeló en Blender y el juego se desarrolló en Unreal Engine 5, con la lógica programada en Blueprints: el patrullaje del enemigo, la validación de claves, la verificación de productos y la victoria.","claves":["blender","unreal","programa","programación","hecho","blueprints","motor","desarrollo","herramientas"]},{"punto":null,"texto":"Es un proyecto de Arllys Ramos y Xavier Ponce para la materia Virtual Games.","claves":["estudiante","estudiantes","autor","autores","quién","quiénes","hicieron","materia"]}]}}$vitrina$::jsonb),
  ('london', 'arquitectura', 50, true,
   $vitrina${"tipo":"maqueta","titulo":"Rascacielos London","ejemplo":true,"ubicacion":"","estudiante":"Arianna Gutiérrez","materia":"[EJEMPLO] Materia por confirmar","periodo":"Semestre 2 - 2026","descripcion":"Torre de oficinas de 32 pisos sobre un podio con lobby a doble altura, de unos 166 m de altura sobre la acera y 27 838 m² de área bruta. El podio tiene un lobby acristalado con recepción, sala de espera y lounge, una escalera abierta hacia el mezzanine (+3,92 m) y una marquesina perimetral sobre columnas elípticas de hormigón. En la torre, las plantas libres de oficinas rodean un núcleo central de ascensores, escaleras y servicios; la planta se ensancha hacia los pisos medios y se estrecha hacia la coronación, con 4,38 m de piso a piso. Remata en un volumen acristalado con azotea técnica y una góndola para el mantenimiento de las fachadas.","portada":"img/london-render.webp","imagenes":[],"galeria":{"titulo":"Planos","estilo":"planos","imagenes":[{"src":"img/london/L-01_Planta_Baja_Lobby.webp","mini":"img/london/L-01_Planta_Baja_Lobby-mini.webp","titulo":"Planta baja (lobby)","alt":"Planta baja con el lobby a doble altura, recepción, sala de espera y núcleo de ascensores"},{"src":"img/london/L-02_Planta_Mezzanine.webp","mini":"img/london/L-02_Planta_Mezzanine-mini.webp","titulo":"Planta mezzanine","alt":"Planta del mezzanine sobre el lobby"},{"src":"img/london/L-03_Planta_Tipo_Piso12.webp","mini":"img/london/L-03_Planta_Tipo_Piso12-mini.webp","titulo":"Planta tipo (piso 12)","alt":"Planta libre de oficinas del piso 12 alrededor del núcleo central"},{"src":"img/london/L-04_Plantas_Tipo_Variacion.webp","mini":"img/london/L-04_Plantas_Tipo_Variacion-mini.webp","titulo":"Plantas tipo: variación","alt":"Variación de las plantas tipo según la altura de la torre"},{"src":"img/london/L-05_Planta_Cubierta.webp","mini":"img/london/L-05_Planta_Cubierta-mini.webp","titulo":"Planta de cubierta","alt":"Planta de la cubierta con la azotea técnica y la góndola de mantenimiento"},{"src":"img/london/L-06_Fachadas.webp","mini":"img/london/L-06_Fachadas-mini.webp","titulo":"Fachadas","alt":"Fachadas de la torre"},{"src":"img/london/L-07_Cortes.webp","mini":"img/london/L-07_Cortes-mini.webp","titulo":"Cortes","alt":"Cortes longitudinal y transversal con los 32 pisos y sus niveles"},{"src":"img/london/L-08_Detalle_Corte_Podio.webp","mini":"img/london/L-08_Detalle_Corte_Podio-mini.webp","titulo":"Detalle del podio","alt":"Detalle del corte del podio con el lobby y el mezzanine"},{"src":"img/london/L-09_Plantas_Presentacion.webp","mini":"img/london/L-09_Plantas_Presentacion-mini.webp","titulo":"Plantas de presentación","alt":"Plantas a color con el mobiliario"},{"src":"img/london/L-10_Cuadro_Areas_Memoria.webp","mini":"img/london/L-10_Cuadro_Areas_Memoria-mini.webp","titulo":"Cuadro de áreas y memoria","alt":"Cuadro de áreas brutas por nivel y memoria descriptiva"}]},"creditoModelo":{"titulo":"[FREE] London Skyscraper","autor":"99.Miles","plataforma":"Sketchfab","url":"https://skfb.ly/pKVG9","licencia":"CC BY 4.0","licenciaUrl":"https://creativecommons.org/licenses/by/4.0/","adaptacion":"Xavier Ponce","cambios":"Planos elaborados a partir del modelo original; para la vitrina se simplificó y optimizó para celular."},"ar":{"modelo":"modelos/london.glb","modeloHero":"modelos/london-hero.glb","poster":"img/london-render.webp","modeloIOS":"","escala":"1:400","camara":"30deg 78deg auto","camaraHero":"30deg 78deg auto","cortes":[{"nombre":"Piso 12","altura":0.1549},{"nombre":"Lobby","altura":0.0239}],"alt":"Maqueta 3D de una torre de oficinas de vidrio oscuro de 32 pisos, que se ensancha en el centro y se estrecha hacia la coronación","puntos":[{"id":"lobby","titulo":"Lobby a doble altura","texto":"El podio tiene un lobby acristalado de 9,58 m de alto, con recepción, sala de espera y lounge, y una escalera abierta hacia el mezzanine (+3,92 m).","posicion":"-0.0008 0.0142 0.0445","normal":"0 0 1"},{"id":"planta-tipo","titulo":"Planta tipo","texto":"Las plantas de oficinas son libres y rodean un núcleo central de ascensores, escaleras y servicios. El piso 12 (+59,38 m) tiene 903 m² brutos.","posicion":"-0.0008 0.1499 0.0600","normal":"0 0 1"},{"id":"coronamiento","titulo":"Coronamiento","texto":"La torre remata en un volumen acristalado con azotea técnica (+150,59 m) y una góndola que recorre las fachadas para su mantenimiento.","posicion":"-0.0011 0.4067 0.027","normal":"0 1 0"}]},"asistente":{"sugeridas":["¿Cuántos pisos tiene la torre?","¿Qué hay en el lobby?","¿Qué altura tiene?"],"pasajes":[{"punto":null,"texto":"La torre tiene 32 pisos de oficinas sobre un podio con lobby y mezzanine.","claves":["pisos","niveles","plantas","cuántos"]},{"punto":null,"texto":"Mide unos 166 m de altura sobre la acera; el piso 32 está a +146,41 m y la azotea técnica a +150,59 m.","claves":["altura","alto","mide","metros","alta"]},{"punto":"lobby","texto":"El lobby acristalado tiene doble altura (9,58 m), recepción, sala de espera y lounge, y una escalera abierta que sube al mezzanine (+3,92 m).","claves":["lobby","entrada","recepción","mezzanine","podio","planta baja"]},{"punto":"planta-tipo","texto":"Las plantas de oficinas son libres y rodean un núcleo central de ascensores, escaleras, servicios y ductos. El piso 12 tiene 903 m² brutos.","claves":["oficinas","planta tipo","núcleo","ascensores","ascensor","piso 12"]},{"punto":null,"texto":"El área bruta total es de 27 838 m². Las plantas se ensanchan hacia los pisos medios (hasta 1 122 m² en el piso 22) y se estrechan hacia la coronación.","claves":["área","m2","metros cuadrados","superficie","tamaño","grande","forma"]},{"punto":"coronamiento","texto":"Arriba hay un volumen acristalado con azotea técnica y una góndola de mantenimiento de fachadas (BMU).","claves":["coronamiento","azotea","techo","cubierta","góndola","arriba","último"]},{"punto":null,"texto":"El podio tiene una marquesina perimetral sobre columnas elípticas de hormigón; los accesos están por el norte y el oeste.","claves":["columnas","marquesina","acceso","accesos","estructura","hormigón"]},{"punto":null,"texto":"Es un proyecto de ejemplo de la estudiante Arianna Gutiérrez para la vitrina de Arquitectura.","claves":["estudiante","autora","autor","quién","hizo","diseñó","materia"]}]}}$vitrina$::jsonb),
  ('cafeteria', 'multimedia', 60, true,
   $vitrina${"tipo":"escenario","titulo":"Cafetería M3D","ubicacion":"","estudiante":"Arllys Ramos","materia":"Modelado 3D","periodo":"Semestre 2 - 2026","descripcion":"Interior de una cafetería inspirada en los diners estadounidenses de los años 50. El piso de damero blanco y negro, los gabinetes turquesa con mesas rosadas y la barra en «L» con taburetes cromados, bajo un plafón con franjas de neón rosa, reúnen los rasgos del estilo retro. Unas puertas dobles con ventanas de ojo de buey llevan a la cocina y una galería de cuadros en blanco y negro decora el muro lateral. La escena está abierta por dos lados, como una casa de muñecas, para mirarla desde cualquier ángulo.","portada":"img/cafeteria-render.webp","imagenes":[],"creditos":[{"etiqueta":"Modelado","texto":"Arllys Ramos (Blender)"},{"etiqueta":"Imágenes","texto":"En la versión web, los cuadros y el damero de la pared se cambiaron por diseños propios de la vitrina, porque las imágenes originales provenían de internet."}],"ar":{"modelo":"modelos/cafeteria.glb","modeloHero":"modelos/cafeteria-hero.glb","poster":"img/cafeteria-render.webp","modeloIOS":"","escala":"1:22","camara":"35deg 58deg 75%","camaraHero":"35deg 58deg 80%","cortes":[{"nombre":"Sin plafón","altura":0.1965}],"cortesDobleCara":false,"alt":"Escenario 3D de una cafetería retro de los años 50 con piso de damero, gabinetes turquesa, mesas rosadas y una barra en L","puntos":[{"id":"gabinetes","titulo":"Gabinetes","texto":"Asientos tipo gabinete tapizados en turquesa, con mesas rosadas, alineados junto al muro: el sello de los diners de los años 50.","posicion":"0.0022 0.0625 0.2157","normal":"0 1 0"},{"id":"barra","titulo":"Barra en «L»","texto":"La barra en «L» con taburetes cromados de asiento turquesa ordena el salón; sobre ella, un plafón con franjas de neón rosa marca la zona de atención.","posicion":"-0.0523 0.0829 -0.0297","normal":"0 1 0"},{"id":"cocina","titulo":"Puertas a la cocina","texto":"Puertas dobles de vaivén con ventanas de ojo de buey separan el salón de la cocina.","posicion":"0.1659 0.0988 -0.2661","normal":"0 0 1"}]},"asistente":{"sugeridas":["¿Qué estilo tiene la cafetería?","¿Qué hay en la barra?","¿Quién la modeló?"],"pasajes":[{"punto":null,"texto":"La cafetería está inspirada en los diners estadounidenses de los años 50: piso de damero, colores turquesa y rosa, cromados y neón.","claves":["estilo","época","años","retro","diner","inspiración","colores","color"]},{"punto":"barra","texto":"La barra tiene forma de «L», con taburetes cromados de asiento turquesa; sobre ella hay un plafón con franjas de neón rosa.","claves":["barra","mostrador","taburetes","banco","neón","plafón","luz"]},{"punto":"gabinetes","texto":"Los gabinetes son asientos tapizados en turquesa con mesas rosadas, alineados junto al muro.","claves":["gabinetes","asientos","mesas","mesa","sillones","sentarse","booth"]},{"punto":"cocina","texto":"Unas puertas dobles de vaivén, con ventanas de ojo de buey, llevan a la cocina.","claves":["puerta","puertas","cocina","ventanas","ojo de buey"]},{"punto":null,"texto":"El piso es un damero blanco y negro, típico de las cafeterías de los años 50.","claves":["piso","suelo","damero","cuadros","ajedrez"]},{"punto":null,"texto":"En el muro lateral hay una galería de tres cuadros en blanco y negro. En la versión web se usan diseños propios de la vitrina.","claves":["cuadros","pared","muro","decoración","arte"]},{"punto":null,"texto":"La escena está abierta por dos lados, como una casa de muñecas, para mirarla desde cualquier ángulo.","claves":["abierta","paredes","ver","ángulo","maqueta"]},{"punto":null,"texto":"La modeló la estudiante Arllys Ramos para la materia Modelado 3D.","claves":["estudiante","autora","autor","quién","modeló","hizo","materia","programa"]}]}}$vitrina$::jsonb)
on conflict (id) do nothing;

